// Gallery settings and optional per-photo text.
//
// Photos are discovered automatically from src/assets/gallery/ (generated by
// `npm run photos`). By default the caption and alt text come from the file
// name, so renaming an original to e.g. "clase-de-ninos.jpg" is enough to get
// the caption "Clase de ninos". Use overrides for accents, punctuation or
// longer descriptions.
//
// Keys are the optimized file name without extension, e.g.
// 'whatsapp-image-2026-11-08-at-09-57-41-3'.

export interface GalleryPhotoText {
  /** Description for screen readers and search engines. */
  alt?: string
  /** Short visible caption. */
  caption?: string
}

export const galleryOverrides: Record<string, GalleryPhotoText> = {
  // 'whatsapp-image-2026-11-08-at-09-57-41-3': {
  //   alt: 'Alumnos practicando una guardia cerrada en el tatami',
  //   caption: 'Clase de técnica',
  // },
}

/** Photos visible before pressing "Ver más fotos", and how many each press adds. */
export const GALLERY_PAGE_SIZE = 12

/** Alt text used when neither the file name nor an override describes the photo. */
export const GALLERY_FALLBACK_ALT = 'Entrenamiento de jiu-jitsu brasileño en Betinho BJJ Madrid'
